<script lang="ts">
	import { onMount } from 'svelte';
	import { ApiError, createParticipant, deactivateParticipant, getEpisode, getParticipants, updateParticipant, type Episode, type Participant, type ParticipantRole } from '$lib/episodes-api';
	import type { PageProps } from './$types';

	let { params }: PageProps = $props();
	const roles: { value: ParticipantRole | 'all'; label: string }[] = [{ value: 'all', label: 'Tous les rôles' }, { value: 'PLAYER', label: 'Joueurs' }, { value: 'PRESENTER', label: 'Présentateurs' }, { value: 'OPERATOR', label: 'Opérateurs' }, { value: 'SCREEN', label: 'Écrans' }];
	let episode = $state<Episode | null>(null); let participants = $state<Participant[]>([]); let search = $state(''); let appliedSearch = $state(''); let selectedRole = $state<ParticipantRole | 'all'>('all'); let name = $state(''); let role = $state<ParticipantRole>('PLAYER'); let isLoading = $state(true); let isSaving = $state(false); let errorMessage = $state('');
	const filteredParticipants = $derived(participants);
	function roleLabel(value: ParticipantRole) { return roles.find((item) => item.value === value)?.label.replace(/s$/, '') ?? value; }
	async function load() { try { const parameters = new URLSearchParams(); if (appliedSearch) parameters.set('search', appliedSearch); if (selectedRole !== 'all') parameters.set('role', selectedRole); [episode, participants] = await Promise.all([getEpisode(params.id), getParticipants(params.id, parameters)]); } catch (error) { errorMessage = error instanceof Error ? error.message : 'Impossible de charger les participants.'; } finally { isLoading = false; } }
	async function add() { if (!name.trim()) { errorMessage = 'Indiquez le nom du participant.'; return; } isSaving = true; errorMessage = ''; try { participants = [...participants, await createParticipant(params.id, { name: name.trim(), role })]; name = ''; } catch (error) { errorMessage = error instanceof ApiError ? error.fieldErrors.name ?? error.message : 'Impossible d’ajouter ce participant.'; } finally { isSaving = false; } }
	async function remove(participant: Participant) { if (!confirm(`Supprimer ${participant.name} de cet épisode ?`)) return; try { await deactivateParticipant(params.id, participant.id); participants = participants.filter((item) => item.id !== participant.id); } catch (error) { errorMessage = error instanceof Error ? error.message : 'Impossible de supprimer ce participant.'; } }
	async function deactivate(participant: Participant) { if (!confirm(`Désactiver ${participant.name} ?`)) return; try { const updated = await updateParticipant(params.id, participant.id, { is_active: false }); participants = participants.map((item) => item.id === participant.id ? updated : item); } catch (error) { errorMessage = error instanceof Error ? error.message : 'Impossible de désactiver ce participant.'; } }
	onMount(() => { void load(); });
</script>

<svelte:head><title>Participants · EpicQuiz - La Grille</title></svelte:head>
<main><a class="back" href={`/episodes/${params.id}`}>← Retour à l’épisode</a>{#if isLoading}<p class="status">Chargement…</p>{:else if errorMessage && !episode}<p class="error" role="alert">{errorMessage}</p>{:else}<header><p>Épisode · {episode?.title}</p><h1>Participants</h1><span>{participants.filter((item) => item.is_active).length} actifs</span></header><section class="creation" aria-labelledby="add-title"><div><p class="eyebrow">Nouvelle personne</p><h2 id="add-title">Ajouter un participant</h2></div><form onsubmit={(event) => { event.preventDefault(); void add(); }}><label>Nom<input bind:value={name} placeholder="Nom du participant" /></label><label>Rôle<select bind:value={role}>{#each roles.slice(1) as option}<option value={option.value}>{option.label}</option>{/each}</select></label><button disabled={isSaving}>{isSaving ? 'Ajout…' : 'Ajouter'}</button></form></section><form class="filters" aria-label="Rechercher et filtrer les participants" onsubmit={(event) => { event.preventDefault(); appliedSearch = search.trim(); void load(); }}><input bind:value={search} type="search" placeholder="Rechercher par nom" aria-label="Rechercher par nom" /><select bind:value={selectedRole} aria-label="Filtrer par rôle">{#each roles as option}<option value={option.value}>{option.label}</option>{/each}</select><button class="search-button" style="min-height:2.7rem;border:0;border-radius:.5rem;padding:0 1rem;background:#7c3aed;color:#fff;cursor:pointer;font:inherit;font-size:.8rem;font-weight:800;white-space:nowrap" type="submit">Rechercher</button></form>{#if errorMessage}<p class="error" role="alert">{errorMessage}</p>{/if}<section class="table" aria-label="Liste des participants"><div class="head"><span>Participant</span><span>Rôle</span><span>Statut</span><span>Actions</span></div>{#each filteredParticipants as participant}<article class:inactive={!participant.is_active}><div><strong>{participant.name}</strong><small>@{participant.username}</small></div><span>{roleLabel(participant.role)}</span><span>{participant.is_active ? 'Actif' : 'Désactivé'}</span><div>{#if participant.is_active && episode?.state === 'pending'}<button class="danger" type="button" onclick={() => void remove(participant)}>Supprimer</button>{:else if participant.is_active}<button class="danger" type="button" onclick={() => void deactivate(participant)}>Désactiver</button>{/if}</div></article>{:else}<p class="empty">Aucun participant ne correspond à ces filtres.</p>{/each}</section>{/if}</main>

<style>
	:global(*){box-sizing:border-box}:global(html),:global(body){margin:0;background:#0f172a;color:#f8fafc;font-family:Inter,ui-sans-serif,system-ui,sans-serif}main{width:min(100%,76rem);min-height:100dvh;margin:auto;padding:clamp(1.25rem,4vw,3rem)}.back{color:#c4b5fd;font-size:.85rem;font-weight:750;text-decoration:none}.back:hover{text-decoration:underline}header{display:flex;align-items:end;gap:1rem;margin:3rem 0 2rem}header p{align-self:center;margin:0 auto 0 0;color:#cbd5e1;font-size:.85rem}h1{margin:0;color:#f8fafc;font-size:clamp(2.3rem,5vw,4rem);letter-spacing:-.06em}h2{margin:.2rem 0 0;color:#f8fafc;font-size:1.1rem}.eyebrow{margin:0;color:#c4b5fd;font-size:.68rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}header span{border-radius:999px;padding:.45rem .7rem;background:rgba(34,197,94,.12);color:#86efac;font-size:.78rem;font-weight:750}.creation{display:grid;grid-template-columns:13rem 1fr;gap:1.25rem;align-items:end;border:1px solid rgba(124,58,237,.6);border-radius:1rem;padding:1.2rem;background:linear-gradient(135deg,rgba(124,58,237,.16),#1e293b)}.creation form,.filters{display:flex;gap:.7rem}.creation label{flex:1;color:#cbd5e1;font-size:.72rem;font-weight:750}.creation input,.creation select,.filters input,.filters select{width:100%;min-height:2.7rem;margin-top:.35rem;border:1px solid #475569;border-radius:.55rem;padding:0 .7rem;background:#0f172a;color:#f8fafc;font:inherit}.creation button{align-self:end;min-height:2.7rem;border:0;border-radius:.55rem;padding:.6rem 1rem;background:#7c3aed;color:#fff;cursor:pointer;font:inherit;font-size:.82rem;font-weight:750}.filters{margin-top:1.5rem}.filters input{flex:1;margin-top:0}.filters select{width:12rem;margin-top:0}.table{margin-top:1rem;border:1px solid #334155;border-radius:1rem;overflow:hidden;background:#1e293b}.head,.table article{display:grid;grid-template-columns:minmax(0,2fr) 1fr 1fr auto;gap:1rem;align-items:center;padding:1rem 1.2rem}.head{background:#17213a;color:#94a3b8;font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.table article{border-top:1px solid #334155}.table strong,.table small{display:block}.table strong{font-size:.9rem}.table small{margin-top:.2rem;color:#94a3b8;font-size:.74rem}.table article>span{color:#cbd5e1;font-size:.82rem}.table article.inactive{opacity:.5}.danger{min-height:2.3rem;border:1px solid rgba(239,68,68,.6);border-radius:.45rem;padding:.35rem .55rem;background:transparent;color:#fca5a5;cursor:pointer;font:inherit;font-size:.75rem;font-weight:750}.empty,.status{padding:3rem;color:#94a3b8;text-align:center}.error{margin:1rem 0;color:#fecaca}.back:focus-visible,.creation :focus-visible,.filters :focus-visible,.danger:focus-visible{outline:3px solid #a78bfa;outline-offset:3px}@media(max-width:700px){header{align-items:flex-start;flex-direction:column;gap:.5rem}.creation{grid-template-columns:1fr}.creation form,.filters{flex-direction:column}.filters select{width:100%}.head{display:none}.table article{grid-template-columns:1fr 1fr}.table article>div:first-child{grid-column:1/-1}.table article>div:last-child{text-align:right}}
</style>
